void begin_dispatch(llvm::Function &F,
                    std::vector<llvm::BasicBlock *> stateBlocks) {
    llvm::BasicBlock *entry = &F.front();
    llvm::BasicBlock *dispatcher =
        llvm::BasicBlock::Create(F.getContext(), "ms.dispatch", &F);
    llvm::BasicBlock *invalidBlock =
        llvm::BasicBlock::Create(F.getContext(), "ms.invalid", &F);

    // Iterator form: insert before entry's first existing instruction.
    llvm::IRBuilder<> setup(&*entry->getFirstInsertionPt());
    llvm::AllocaInst *stateSlot =
        setup.CreateAlloca(setup.getInt32Ty(), nullptr, "ms.state");

    // Pointer form: both fresh blocks are empty, so the end of the block is
    // the only legal position. Each builder keeps its own insertion point.
    llvm::IRBuilder<> invalidBuilder(invalidBlock);
    invalidBuilder.CreateUnreachable();

    llvm::IRBuilder<> dispatch(dispatcher);
    llvm::Value *current =
        dispatch.CreateLoad(dispatch.getInt32Ty(), stateSlot, "ms.current");
    llvm::SwitchInst *sw = dispatch.CreateSwitch(
        current, invalidBlock, static_cast<unsigned>(stateBlocks.size()));
